// insert the slot (the key refuses a double take), delete the ticket, log it.
func (q *Queries) UpsertGitHubJob(ctx context.Context, arg UpsertGitHubJobParams) error {
	_, err := q.exec(ctx, q.upsertGitHubJobStmt, upsertGitHubJob,
		arg.ID,
		arg.RepositoryID,
		arg.RunID,
		arg.RunAttempt,
		arg.Workflow,
		arg.JobName,
		arg.HeadSha,
		arg.HeadBranch,
		arg.Event,
		arg.FromFork,
		arg.Labels,
		arg.Status,
		arg.Conclusion,
		arg.RunnerName,
		arg.CreatedAtGithub,
		arg.StartedAtGithub,
		arg.CompletedAtGithub,
	)
	return err
}
